package com.vandorlabs.vehicle;

import com.vandorlabs.coupler.*;
import com.vandorlabs.gear.*;
import com.vandorlabs.gear.core.GearMotion;
import java.lang.reflect.Method;
import java.lang.reflect.Constructor;
import java.util.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;

/** Detached chosen-partition mapping. Real transfer/authorization is deliberately not bypassed. */
public final class ArmCouplerPartitionReceiptChecks {
    private static int checks;
    private static void need(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
    private static void refuses(Runnable action){try{action.run();throw new AssertionError("Invalid chosen partition admitted");}catch(IllegalArgumentException expected){checks++;}}
    private static NBTTagCompound data(int id){NBTTagCompound data=new NBTTagCompound();data.setString("id","vandorlabs:square_coupler");data.setUniqueId("CouplerControlIdentity",new UUID(700,id));data.setBoolean("CouplerRequested",true);data.setBoolean("CouplerArticulation",true);NBTTagCompound cap=new NBTTagCompound();cap.setByteArray("Opaque",new byte[]{3,1,4});data.setTag("ForgeCaps",cap);data.setString("FutureOwn","exact");return data;}
    public static void main(String[] args)throws Exception{
        net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileCoupler.class,new ResourceLocation("vandorlabs:square_coupler"));net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(GearTileEntity.class,new ResourceLocation("vandorlabs:modular_gear"));net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(GearRegistry.GEAR_EXTENDER);BlockCoupler block=new BlockCoupler();net.minecraftforge.fml.common.registry.ForgeRegistries.BLOCKS.register(block);
        Constructor<?> constructor=Class.forName("com.vandorlabs.client.NonRenderingChecks$MemoryWorld").getDeclaredConstructor(boolean.class);constructor.setAccessible(true);World world=(World)constructor.newInstance(false);
        BlockPos a=new BlockPos(3,2,1),b=a.east(),c=new BlockPos(3,2,5),d=c.east();List<VehicleStructure.Cell> cells=new ArrayList<>();int index=1;for(BlockPos p:Arrays.asList(a,b,c,d))cells.add(new VehicleStructure.Cell(p,block.getDefaultState().withProperty(BlockCoupler.FACING,p.equals(a)||p.equals(c)?EnumFacing.EAST:EnumFacing.WEST).withProperty(BlockCoupler.LOCKED,true),data(index++)));
        VehicleStructure original=VehicleStructure.display(cells);VehicleArmCouplers.Snapshot prior=VehicleArmCouplers.observe(original,new VehicleWorld(world,original));need(VehicleArmCouplerPairs.discoverForParking(prior).pairs.size()==2,"complete actual prior has both pairs");NBTTagCompound before=original.write();UUID owner=new UUID(10,11),generation=new UUID(12,13);
        VehicleStructure renewed=VehicleArmCouplerReceipts.partition(prior,original,original,BlockPos.ORIGIN,owner,generation,Collections.emptySet());for(VehicleStructure.Cell cell:renewed.couplers){CouplerAssociation proof=CouplerAssociationData.read(cell.tileData());need(proof.state==CouplerAssociation.EXPECTED_PAIR&&proof.scope(cell.tileData().getUniqueId("CouplerControlIdentity"),owner,generation),"every retained head renews scope as paired");need(cell.tileData().getCompoundTag("ForgeCaps").equals(original.at(cell.pos).tileData().getCompoundTag("ForgeCaps")),"opaque caps exact");}need(original.write().equals(before),"chosen renewal does not mutate original source");
        VehicleArmCouplers.Snapshot scoped=VehicleArmCouplers.observe(renewed,new VehicleWorld(world,renewed,VehicleWorld.CouplerScope.external(owner,generation)));Set<VehicleArmCouplers.Address> release=new HashSet<>(Arrays.asList(VehicleArmCouplers.Address.nativeCell(a),VehicleArmCouplers.Address.nativeCell(b)));
        List<VehicleStructure.Cell> selected=new ArrayList<>();for(VehicleStructure.Cell cell:renewed.cells)if(!cell.pos.equals(b)){NBTTagCompound tag=cell.tileData();if(cell.pos.equals(a))tag.setBoolean("VehicleArmCouplerReleased",true);selected.add(new VehicleStructure.Cell(cell.pos.subtract(a),cell.state,VehicleTileData.translated(tag,BlockPos.ORIGIN.subtract(a))));}VehicleStructure shifted=VehicleStructure.display(selected);UUID nextOwner=new UUID(20,21),nextGeneration=new UUID(22,23);VehicleStructure partition=VehicleArmCouplerReceipts.partition(scoped,renewed,shifted,a,nextOwner,nextGeneration,release);need(CouplerAssociationData.read(partition.at(BlockPos.ORIGIN).tileData()).state==CouplerAssociation.UNPAIRED,"actual selected release becomes unpaired");need(CouplerAssociationData.read(partition.at(c.subtract(a)).tileData()).state==CouplerAssociation.EXPECTED_PAIR,"unrelated retained pair remains paired after shift");
        refuses(()->VehicleArmCouplerReceipts.partition(scoped,renewed,shifted,a,nextOwner,nextGeneration,Collections.emptySet()));refuses(()->VehicleArmCouplerReceipts.partition(scoped,renewed,shifted,a,nextOwner,nextGeneration,Collections.singleton(VehicleArmCouplers.Address.nativeCell(a))));
        List<VehicleStructure.Cell> missingMark=new ArrayList<>(shifted.cells);NBTTagCompound noMark=missingMark.get(0).tileData();noMark.removeTag("VehicleArmCouplerReleased");missingMark.set(0,new VehicleStructure.Cell(BlockPos.ORIGIN,missingMark.get(0).state,noMark));refuses(()->VehicleArmCouplerReceipts.partition(scoped,renewed,VehicleStructure.display(missingMark),a,nextOwner,nextGeneration,release));
        List<VehicleStructure.Cell> duplicateIdentity=new ArrayList<>(original.cells);NBTTagCompound duplicate=duplicateIdentity.get(1).tileData();duplicate.setUniqueId("CouplerControlIdentity",duplicateIdentity.get(0).tileData().getUniqueId("CouplerControlIdentity"));duplicateIdentity.set(1,new VehicleStructure.Cell(b,duplicateIdentity.get(1).state,duplicate));refuses(()->VehicleArmCouplerReceipts.partition(prior,original,VehicleStructure.display(duplicateIdentity),BlockPos.ORIGIN,owner,generation,Collections.emptySet()));
        List<VehicleStructure.Cell> changedContents=new ArrayList<>(original.cells);NBTTagCompound changed=changedContents.get(0).tileData();changed.getCompoundTag("ForgeCaps").setString("Changed","forbidden");changedContents.set(0,new VehicleStructure.Cell(a,cells.get(0).state,changed));refuses(()->VehicleArmCouplerReceipts.partition(prior,original,VehicleStructure.display(changedContents),BlockPos.ORIGIN,owner,generation,Collections.emptySet()));
        List<VehicleStructure.Cell> changedGeometry=new ArrayList<>(original.cells);changedGeometry.set(0,new VehicleStructure.Cell(a,cells.get(0).state.withProperty(BlockCoupler.FACING,EnumFacing.NORTH),cells.get(0).tileData()));refuses(()->VehicleArmCouplerReceipts.partition(prior,original,VehicleStructure.display(changedGeometry),BlockPos.ORIGIN,owner,generation,Collections.emptySet()));
        List<VehicleStructure.Cell> unknown=new ArrayList<>(original.cells);unknown.add(new VehicleStructure.Cell(new BlockPos(9,2,1),cells.get(0).state,data(99)));refuses(()->VehicleArmCouplerReceipts.partition(prior,original,VehicleStructure.display(unknown),BlockPos.ORIGIN,owner,generation,Collections.emptySet()));
        Constructor<ArmPayload> payloadConstructor=ArmPayload.class.getDeclaredConstructor(VehicleStructure.class,BlockPos.class,boolean.class,BlockPos.class);payloadConstructor.setAccessible(true);Method tagger=ArmCouplerHeadChecks.class.getDeclaredMethod("gearTag",BlockPos.class,EnumFacing.class,GearMotion.Mode.class,double.class,NBTTagCompound.class);tagger.setAccessible(true);
        BlockPos root=new BlockPos(12,12,12),offset=new BlockPos(2,2,2),headAt=root.add(offset);
        for(EnumFacing mount:EnumFacing.values())for(EnumFacing facing:EnumFacing.values())for(boolean materialized:new boolean[]{false,true}){
            net.minecraft.block.state.IBlockState state=block.getDefaultState().withProperty(BlockCoupler.FACING,facing).withProperty(BlockCoupler.LOCKED,true);ArmPayload payload=payloadConstructor.newInstance(VehicleStructure.display(Collections.singletonList(new VehicleStructure.Cell(BlockPos.ORIGIN,state,data(51)))),offset,false,offset);NBTTagCompound armTag=(NBTTagCompound)tagger.invoke(null,root,mount,GearMotion.Mode.EXTEND,1D,payload.write());BlockPos mate=headAt.offset(facing);List<VehicleStructure.Cell> layout=new ArrayList<>();layout.add(new VehicleStructure.Cell(root,GearRegistry.GEAR_EXTENDER.getDefaultState(),armTag));layout.add(new VehicleStructure.Cell(mate,state.withProperty(BlockCoupler.FACING,facing.getOpposite()),VehicleTileData.translated(data(52),mate)));VehicleStructure raw=VehicleStructure.display(layout);VehicleWorld rawView=new VehicleWorld(world,raw);
            if(materialized){GearTileEntity gear=(GearTileEntity)rawView.tiles.get(root);ArmGridPlacement placement=gear.payload().gridPlacement(gear,1);need(placement!=null,"real materialized mapping available");armTag.setTag("ArmPayload",placement.payloadTag());layout.set(0,new VehicleStructure.Cell(root,GearRegistry.GEAR_EXTENDER.getDefaultState(),armTag));layout.addAll(placement.cells);raw=VehicleStructure.display(layout);rawView=new VehicleWorld(world,raw);}
            VehicleArmCouplers.Snapshot observed=VehicleArmCouplers.observe(raw,rawView);NBTTagCompound rawBefore=raw.write();VehicleStructure chosen=VehicleArmCouplerReceipts.partition(observed,raw,raw,BlockPos.ORIGIN,owner,generation,Collections.emptySet());ArmPayload chosenPayload=ArmPayload.readForCouplerReceipt(chosen.at(root).tileData().getCompoundTag("ArmPayload"));CouplerAssociation headProof=CouplerAssociationData.read(chosenPayload.blocks.at(BlockPos.ORIGIN).tileData());need(headProof.state==CouplerAssociation.EXPECTED_PAIR&&headProof.scope(new UUID(700,51),owner,generation),"captured header receives complete chosen scope");need(chosenPayload.materialized()==materialized&&raw.write().equals(rawBefore),"mapping ownership and immutable original retained");if(materialized)need(CouplerAssociationData.read(chosen.at(headAt).tileData()).head.equals(headProof.head),"materialized native and retained header use one head identity");VehicleWorld chosenView=new VehicleWorld(world,chosen,VehicleWorld.CouplerScope.external(owner,generation));need(VehicleArmCouplerPairs.discoverForParking(VehicleArmCouplers.observe(chosen,chosenView)).pairs.size()==1,"chosen complete pair readmits under external scope");
        }
        need(original.write().equals(before),"all refusals retain exact prior source");System.out.println("Arm Coupler partition receipts PASS checks="+checks+" complete pairs/shift/all heads/scoped release/opaque/no loss; no runtime publication claim");
    }
}
